var JM_FALLBACK=['www.cdntwice.org','www.cdnsha.org','www.cdnaspa.cc','www.cdnntr.cc'];
var JM_IMG='https://cdn-msp.jmapinodeudzn.net';
function jm_decrypt(data,t){
  var secret=t+'185Hcomic3PAPP7R';
  var key=java.hexDecodeToByteArray(java.md5Encode(secret));
  var dec=java.createSymmetricCrypto('AES/ECB/PKCS5Padding',key,null).decrypt(java.base64DecodeToByteArray(data));
  var s=java.bytesToStr(dec,'UTF-8');
  var start=0;while(start<s.length&&s.charAt(start)!=='{'&&s.charAt(start)!=='[')start++;
  var end=s.length-1;while(end>start&&s.charAt(end)!=='}'&&s.charAt(end)!==']')end--;
  return s.substring(start,end+1);
}
function jm_api(){
  var api=java.get('jm_api');
  if(api)return api;
  try{
    var txt=java.ajax('https://rup4a04-c02.tos-cn-hongkong.bytepluses.com/newsvr-2025.txt');
    var key=java.hexDecodeToByteArray(java.md5Encode('diosfjckwpqpdfjkvnqQjsik'));
    var dec=java.createSymmetricCrypto('AES/ECB/PKCS5Padding',key,null).decrypt(java.base64DecodeToByteArray(txt));
    var s=java.bytesToStr(dec,'UTF-8');
    var i=s.indexOf('"Server"');
    var a=s.indexOf('[',i);var b=s.indexOf(']',i);
    if(i>=0&&a>=0&&b>a){
      var servers=JSON.parse(s.substring(a,b+1));
      if(servers&&servers.length>0){api='https://'+servers[0];java.put('jm_api',api);return api;}
    }
  }catch(e){}
  for(var i=0;i<JM_FALLBACK.length;i++){
    var base='https://'+JM_FALLBACK[i];
    try{
      var r=java.ajax(base+'/search?search_query=test&o=mr');
      var j=JSON.parse(r);
      if(j&&typeof j.data==='string'){java.put('jm_api',base);return base;}
    }catch(e){}
  }
  return 'https://'+JM_FALLBACK[0];
}

